from pathlib import Path
import sys,json
sys.path.insert(0,'tools');from loader import loader
base={'schemaVersion':'2.0.0','forceSandbox':True,'mapMode':'outdoor','pcPlace':'r','pcSpot':'outdoor','meta':{'areaName':'Kiểm 4 lỗi đã sửa'},'places':[{'id':'r','name':'Sân công trình','type':'OUT_BUILDING_YARD'}],'actors':[{'name':'PC','isPC':True,'placeId':'r','spot':'outdoor'}],'events':[]}
s=loader('../dist/',base)
s+='''<section style="position:fixed;bottom:0;left:0;right:0;z-index:100;background:#eee4d1;border:2px solid #997b56;padding:12px;font:14px Georgia;color:#49362b"><b>REVIEW 4 LỖI — dữ liệu mẫu, không phải RP</b><div style="display:flex;gap:8px;flex-wrap:wrap;margin:8px 0"><button id="demo-state">1. 5 ghế → broken (vẫn 5)</button><button id="demo-count">2. Outdoor 60 ghế (đủ hình)</button><button id="demo-xray">3. Đặt PC để thử hover/chạm X-Ray</button><button id="demo-clear">PC rời vùng che (phục hồi)</button><button id="demo-visual">4. Visual tốt + 3 hình lỗi</button></div><div id="demo-result" role="status">Chọn một tình huống để xem kết quả.</div></section><script>
const result=document.getElementById('demo-result'),fixture=JSON.parse(document.getElementById('map-data').textContent);async function demo(props,type='OUT_COURTYARD',mode='outdoor'){const d=structuredClone(fixture);d.mapMode=mode;d.pcSpot=mode==='indoor'?'inside':'outdoor';d.actors[0].spot=d.pcSpot;d.places[0]={id:'r',name:type,type,propsMode:'replace',props};await WZWMap.render(d)}
document.getElementById('demo-state').onclick=async()=>{await demo([{id:'chairs',name:'Ghế',item:'seat.dining',count:5,op:'add'},{id:'chairs',name:'Ghế',state:'broken'}]);result.textContent='Count sau sửa state: '+WZW_SCENE.places[0].inventory.objects[0].count+'; xem trạng thái broken ở Inspector.'};
document.getElementById('demo-count').onclick=async()=>{await demo([{name:'Ghế',item:'seat.dining',count:60,op:'add'}]);result.textContent='Đã vẽ '+document.querySelectorAll('[data-rp-instance]').length+' ghế. Map mở rộng, dùng zoom/pan để xem; không cắt ở y=760.'};
document.getElementById('demo-xray').onclick=async()=>{await WZWMap.render(structuredClone(fixture));const state=WZWTemplateUI.state,r=state.records.find(r=>r.node.dataset.occluder==='building'&&r.mask);if(!r){result.textContent='FAIL: thiếu occluder';return;}const m=r.mask;let point;for(let y=Math.floor(m.h*.3);y<m.h*.7&&!point;y++)for(let x=0;x<m.w;x++)if(m.pixels[(y*m.w+x)*4+3]>100){point={x:m.box.x+(x+.5)/m.w*m.box.w,y:m.box.y+(y+.5)/m.h*m.box.h};break;}await state.mountActors([{name:'PC kiểm che',placeId:'r',tagType:'unknown',scenePoint:point,footstep:'hidden'}]);result.textContent='Chưa tương tác: nhà giữ opacity 1. Rê chuột/click/chạm vào nhà hoặc ribbon PC để mờ 0.3; rời chuột hoặc chạm lần nữa để phục hồi.'};
document.getElementById('demo-clear').onclick=async()=>{await WZWTemplateUI.state.mountActors([]);result.textContent='Đã bỏ actor kiểm che. Số công trình còn mờ: '+document.querySelectorAll('.occluded').length+' (mong đợi 0).'};
document.getElementById('demo-visual').onclick=async()=>{await demo([{name:'Hình ngoài khung',visual:{shapes:[{kind:'rect',x:500,y:500,width:10,height:10}]}},{name:'Path hỏng',visual:{shapes:[{kind:'path',d:'M'}]}},{name:'Path thiếu số',visual:{shapes:[{kind:'path',d:'M0 0 L20'}]}},{name:'Hình hợp lệ',visual:{shapes:[{kind:'rect',x:10,y:10,width:70,height:60,material:'wood'}]}}],'OFFICE','indoor');result.textContent='Visual hợp lệ: '+document.querySelectorAll('[data-rp-instance]').length+'; fallback: '+document.querySelectorAll('[data-prop-fallback]').length+' (mong đợi 1 / 3).'};
for(const button of document.querySelectorAll('[id^=demo-]')){if(button.tagName!=='BUTTON')continue;const action=button.onclick;button.onclick=async()=>{const buttons=[...document.querySelectorAll('section button')];buttons.forEach(b=>b.disabled=true);try{await action()}catch(e){result.textContent='Lỗi kiểm: '+e.message}finally{buttons.forEach(b=>b.disabled=false)}};}
</script>'''
Path('examples/WIZAMAP_MECHANISMS_CHECK.html').write_text(s)
